import { useState, useEffect, useCallback } from 'react';
import { generateId } from '../../utils/helpers';

const API      = 'http://localhost:5000/api';
const getToken = () => localStorage.getItem('examai_token');
const DRAFT_KEY = 'examai_draft_exam';

const CreateExam = ({ store }) => {
  const [step,         setStep]         = useState(1);
  const [examData,     setExamData]     = useState({ title: '', description: '', duration_minutes: 30, total_marks: 50, start_time: '', end_time: '' });
  const [createdExam,  setCreatedExam]  = useState(null);
  const [aiConfig,     setAiConfig]     = useState({ topic: '', difficulty: 'Medium', count: 5, type: 'MCQ' });
  const [genQuestions, setGenQuestions] = useState([]);
  const [generating,   setGenerating]   = useState(false);
  const [genProgress,  setGenProgress]  = useState({ current: 0, total: 0 });
  const [aiError,      setAiError]      = useState('');
  const [addTab,       setAddTab]       = useState('ai');
  const [manualQ,      setManualQ]      = useState({ question_text: '', question_type: 'MCQ', difficulty: 'Medium', correct_answer: '', marks: 5, explanation: '', options: ['', '', '', ''] });
  const [showDraftBanner, setShowDraftBanner] = useState(false);
  const [draftInfo,    setDraftInfo]    = useState(null);
  const [showAbandonModal, setShowAbandonModal] = useState(false);

  // ── Computed ──────────────────────────────────────────────
  const savedQuestions = createdExam ? store.getExamQuestions(createdExam.exam_id) : [];
  const questionCount  = savedQuestions.length;
  const currentMarks   = savedQuestions.reduce((s, q) => s + Number(q.marks), 0);
  const examTotal      = createdExam ? Number(createdExam.total_marks) : 0;
  const marksMatch     = currentMarks === examTotal;
  const marksOver      = currentMarks > examTotal;
  const marksLeft      = examTotal - currentMarks;
  const savedTexts     = savedQuestions.map(q => q.question_text.trim().toLowerCase());
  const isPublished    = createdExam ? store.exams.find(e => e.exam_id === createdExam.exam_id)?.status === 'published' : false;
  const acceptedCount  = genQuestions.filter(q => q._accepted && !q._saved).length;
  const acceptedMarks  = genQuestions.filter(q => q._accepted && !q._saved).reduce((s, q) => s + Number(q.marks), 0);
  const allSaved       = genQuestions.filter(q => q._accepted).every(q => q._saved);
  const pct            = examTotal > 0 ? Math.min(100, (currentMarks / examTotal) * 100) : 0;

  // ── Check for draft on mount ──────────────────────────────
  useEffect(() => {
    const draft = JSON.parse(localStorage.getItem(DRAFT_KEY) || 'null');
    if (draft && draft.exam_id) {
      setDraftInfo(draft);
      setShowDraftBanner(true);
    }
  }, []);

  // ── Save draft whenever createdExam changes ───────────────
  useEffect(() => {
    if (createdExam) {
      localStorage.setItem(DRAFT_KEY, JSON.stringify({
        exam_id: createdExam.exam_id,
        title: createdExam.title,
        total_marks: createdExam.total_marks,
        saved_at: new Date().toISOString(),
      }));
    }
  }, [createdExam]);

  // ── Clear draft on component unmount if still incomplete ──
  // (we DON'T delete from DB — admin can resume via Exams tab)

  const resumeDraft = async () => {
    if (!draftInfo) return;
    try {
      const r = await fetch(`${API}/exams/${draftInfo.exam_id}`, {
        headers: { Authorization: `Bearer ${getToken()}` }
      });
      const exam = r.ok ? await r.json() : null;
      if (exam && exam.exam_id) {
        setCreatedExam(exam);
        await store.loadExamQuestions(exam.exam_id);
        setStep(2);
        setShowDraftBanner(false);
        store.addToast('Resumed draft exam', 'success');
      } else {
        localStorage.removeItem(DRAFT_KEY);
        setShowDraftBanner(false);
        store.addToast('Draft exam no longer exists', 'error');
      }
    } catch { store.addToast('Could not resume draft', 'error'); }
  };

  const discardDraft = async () => {
    if (!draftInfo) return;
    try {
      await fetch(`${API}/exams/${draftInfo.exam_id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${getToken()}` }
      });
    } catch {}
    localStorage.removeItem(DRAFT_KEY);
    setShowDraftBanner(false);
    setDraftInfo(null);
    store.addToast('Draft discarded', 'info');
  };

  // ── Step 1 ────────────────────────────────────────────────
  const handleExamCreate = async () => {
    if (!examData.title.trim()) return store.addToast('Title is required', 'error');
    if (Number(examData.total_marks) < 1) return store.addToast('Total marks must be at least 1', 'error');
    if (Number(examData.duration_minutes) < 1) return store.addToast('Duration must be at least 1 minute', 'error');
    const exam = await store.createExam(examData);
    if (!exam) return;
    setCreatedExam(exam);
    setStep(2);
    store.addToast(`Exam created! Add exactly ${exam.total_marks} marks worth of questions.`, 'success');
  };

  // ── Abandon current exam ─────────────────────────────────
  const handleAbandon = async () => {
    setShowAbandonModal(false);
    if (createdExam && questionCount === 0) {
      // No questions yet → delete the empty exam from DB
      try {
        await fetch(`${API}/exams/${createdExam.exam_id}`, {
          method: 'DELETE',
          headers: { Authorization: `Bearer ${getToken()}` }
        });
        store.addToast('Exam deleted (no questions had been added)', 'info');
      } catch {}
    } else if (createdExam) {
      store.addToast('Exam saved as draft in "All Exams". You can continue adding questions later.', 'info');
    }
    localStorage.removeItem(DRAFT_KEY);
    setCreatedExam(null);
    setStep(1);
    setGenQuestions([]);
    setAiError('');
    setExamData({ title: '', description: '', duration_minutes: 30, total_marks: 50, start_time: '', end_time: '' });
  };

  // ── AI Generate ───────────────────────────────────────────
  const handleGenerate = async () => {
    if (!aiConfig.topic) return store.addToast('Enter a topic first', 'error');
    if (marksLeft <= 0) return store.addToast('Marks are full! Remove questions first.', 'error');
    setGenerating(true); setAiError(''); setGenQuestions([]);
    setGenProgress({ current: 0, total: Number(aiConfig.count) });
    try {
      const { generateQuestions } = await import('../../utils/aiService');
      const qs = await generateQuestions(
        { ...aiConfig, count: Number(aiConfig.count) },
        (current, t) => setGenProgress({ current, total: t })
      );
      const unique = qs.filter((q, i, a) =>
        a.findIndex(x => x.question_text.trim().toLowerCase() === q.question_text.trim().toLowerCase()) === i
      );
      // Auto-fit marks: adjust generated question marks to fit remaining budget
      const autoFitted = autoFitMarks(unique, marksLeft);
      setGenQuestions(autoFitted.map(q => ({ ...q, exam_id: createdExam.exam_id, _accepted: true, _saved: false })));
      store.addToast(`Generated ${unique.length} questions! Marks auto-fitted to budget.`, 'success');
    } catch (e) { setAiError('Generation failed: ' + e.message); }
    setGenerating(false);
  };

  // Auto-fit: redistribute marks so total accepted = exactly marksLeft
  const autoFitMarks = (questions, budget) => {
    if (!questions.length || budget <= 0) return questions;
    const perQ     = Math.floor(budget / questions.length);
    const remainder= budget % questions.length;
    return questions.map((q, i) => ({ ...q, marks: perQ + (i < remainder ? 1 : 0) }));
  };

  const toggleAccept = (idx) =>
    setGenQuestions(qs => qs.map((q, i) => i === idx ? { ...q, _accepted: !q._accepted } : q));

  const editMarks = (idx, val) => {
    const v = Math.max(1, Number(val) || 1);
    setGenQuestions(qs => qs.map((q, i) => i === idx ? { ...q, marks: v } : q));
  };

  // Re-fit marks when accept/reject changes
  const rebalanceMarks = useCallback(() => {
    const accepted = genQuestions.filter(q => q._accepted && !q._saved);
    if (!accepted.length) return;
    const perQ  = Math.floor(marksLeft / accepted.length);
    const rem   = marksLeft % accepted.length;
    let ri = 0;
    setGenQuestions(qs => qs.map(q => {
      if (!q._accepted || q._saved) return q;
      const m = perQ + (ri < rem ? 1 : 0);
      ri++;
      return { ...q, marks: Math.max(1, m) };
    }));
  }, [genQuestions, marksLeft]);

  const handleSaveAccepted = () => {
    const toSave    = genQuestions.filter(q => q._accepted && !q._saved);
    if (!toSave.length) return store.addToast('No accepted questions to save', 'error');
    const wouldAdd  = toSave.reduce((s, q) => s + Number(q.marks), 0);
    const newTotal  = currentMarks + wouldAdd;
    if (newTotal > examTotal) {
      return store.addToast(
        `Would exceed ${examTotal} marks (${currentMarks} used + ${wouldAdd} adding = ${newTotal}). Click "Rebalance" to auto-fix, or reject some questions.`,
        'error'
      );
    }
    const dupes = toSave.filter(q => savedTexts.includes(q.question_text.trim().toLowerCase()));
    if (dupes.length > 0) return store.addToast(`${dupes.length} duplicate question(s) — reject them first.`, 'error');
    const clean = toSave.map(({ _accepted, _saved, ...q }) => q);
    store.addQuestions(clean, examTotal);
    setGenQuestions(qs => qs.map(q => q._accepted ? { ...q, _saved: true } : q));
    store.addToast(`${toSave.length} questions saved!`, 'success');
  };

  // ── Manual Add ────────────────────────────────────────────
  const handleAddManual = () => {
    if (!manualQ.question_text.trim()) return store.addToast('Question text required', 'error');
    const qMarks = Number(manualQ.marks);
    if (currentMarks + qMarks > examTotal)
      return store.addToast(`Cannot add: only ${marksLeft} marks remaining.`, 'error');
    if (savedTexts.includes(manualQ.question_text.trim().toLowerCase()))
      return store.addToast('This question already exists in the exam.', 'error');
    const q = {
      ...manualQ, question_id: generateId(), exam_id: createdExam.exam_id, marks: qMarks,
      options: manualQ.question_type === 'MCQ'
        ? manualQ.options.map((o, i) => ({ option_id: generateId(), text: o, is_correct: ['A','B','C','D'][i] === manualQ.correct_answer }))
        : undefined,
    };
    store.addQuestions([q], examTotal);
    store.addToast('Question added!', 'success');
    setManualQ({ question_text: '', question_type: 'MCQ', difficulty: 'Medium', correct_answer: '', marks: Math.min(marksLeft - qMarks, 10), explanation: '', options: ['', '', '', ''] });
  };

  // ── Publish ───────────────────────────────────────────────
  const handlePublish = async () => {
    const r = await fetch(`${API}/exams/${createdExam.exam_id}/publish`, {
      method: 'POST', headers: { Authorization: `Bearer ${getToken()}` }
    });
    const d = await r.json();
    if (d.error) { store.addToast(d.error, 'error'); return; }
    localStorage.removeItem(DRAFT_KEY);
    store.addToast('Exam published! Students can now see it.', 'success');
    store.setExams(es => es.map(e => e.exam_id === createdExam.exam_id ? { ...e, status: 'published' } : e));
  };

  // ── Colour helpers ────────────────────────────────────────
  const barColor = marksOver ? '#dc2626' : marksMatch ? '#16a34a' : '#7c3aed';
  const bannerBg = marksOver ? '#fef2f2' : marksMatch ? '#f0fdf4' : '#faf5ff';
  const bannerBdr= marksOver ? '#fecaca' : marksMatch ? '#bbf7d0' : '#ddd6fe';
  const marksColor=marksOver ? '#dc2626' : marksMatch ? '#16a34a' : '#7c3aed';

  return (
    <div style={{ maxWidth: 860 }}>

      {/* Draft resume banner */}
      {showDraftBanner && draftInfo && (
        <div style={{ background: '#fef9c3', border: '1.5px solid #fde68a', borderRadius: 12, padding: '14px 18px', marginBottom: 20, display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap' }}>
          <span style={{ fontSize: 20 }}>📝</span>
          <div style={{ flex: 1 }}>
            <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, fontSize: 14, color: '#713f12', marginBottom: 3 }}>
              Unfinished Exam Found
            </div>
            <div style={{ fontSize: 12, color: '#92400e' }}>
              "{draftInfo.title}" ({draftInfo.total_marks} marks) — saved {new Date(draftInfo.saved_at).toLocaleString()}
            </div>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button onClick={resumeDraft}
              style={{ padding: '7px 18px', background: '#16a34a', color: '#fff', border: 'none', borderRadius: 8, fontWeight: 700, fontSize: 12, cursor: 'pointer' }}>
              Resume
            </button>
            <button onClick={discardDraft}
              style={{ padding: '7px 18px', background: '#fff', color: '#dc2626', border: '1px solid #fecaca', borderRadius: 8, fontWeight: 700, fontSize: 12, cursor: 'pointer' }}>
              Discard
            </button>
          </div>
        </div>
      )}

      {/* Step indicator */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 0, marginBottom: 24 }}>
        {[1, 2].map(s => (
          <div key={s} style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
            <div style={{ width: 30, height: 30, borderRadius: '50%', background: step >= s ? '#7c3aed' : '#f3f4f6', border: `2px solid ${step >= s ? '#7c3aed' : '#e5e7eb'}`, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12, fontWeight: 800, color: step >= s ? '#fff' : '#9ca3af', transition: 'all .2s' }}>{s}</div>
            <span style={{ fontSize: 13, fontWeight: step >= s ? 700 : 400, color: step >= s ? '#0f0f1a' : '#9ca3af' }}>{s === 1 ? 'Exam Setup' : 'Add Questions'}</span>
            {s < 2 && <div style={{ width: 32, height: 2, background: step >= 2 ? '#7c3aed' : '#e5e7eb', margin: '0 6px', borderRadius: 2, transition: 'all .2s' }}/>}
          </div>
        ))}
      </div>

      {/* ════════════════ STEP 1 ════════════════ */}
      {step === 1 && (
        <div style={{ background: '#fff', border: '1px solid #e8e8f0', borderRadius: 16, padding: 28, boxShadow: '0 1px 4px rgba(0,0,0,.06)' }}>
          <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 800, fontSize: 20, color: '#0f0f1a', marginBottom: 20 }}>Create New Exam</div>

          <div style={{ marginBottom: 14 }}>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>EXAM TITLE *</label>
            <input className="form-input" value={examData.title} onChange={e => setExamData(d => ({ ...d, title: e.target.value }))} placeholder="e.g. Introduction to Machine Learning"/>
          </div>

          <div style={{ marginBottom: 14 }}>
            <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>DESCRIPTION</label>
            <textarea className="form-textarea" value={examData.description} onChange={e => setExamData(d => ({ ...d, description: e.target.value }))} placeholder="Brief description..." style={{ minHeight: 80 }}/>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14, marginBottom: 14 }}>
            <div>
              <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>DURATION (MINUTES)</label>
              <input className="form-input" type="number" min={1} value={examData.duration_minutes} onChange={e => setExamData(d => ({ ...d, duration_minutes: e.target.value }))}/>
            </div>
            <div>
              <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>TOTAL MARKS *</label>
              <input className="form-input" type="number" min={1} max={1000} value={examData.total_marks} onChange={e => setExamData(d => ({ ...d, total_marks: e.target.value }))}/>
              <div style={{ fontSize: 11, color: '#9ca3af', marginTop: 4 }}>Questions must add up to exactly this number</div>
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 14, marginBottom: 22 }}>
            <div>
              <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>START TIME</label>
              <input className="form-input" type="datetime-local" value={examData.start_time} onChange={e => setExamData(d => ({ ...d, start_time: e.target.value }))}/>
            </div>
            <div>
              <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>END TIME</label>
              <input className="form-input" type="datetime-local" value={examData.end_time} onChange={e => setExamData(d => ({ ...d, end_time: e.target.value }))}/>
            </div>
          </div>

          {/* Marks preview box */}
          <div style={{ background: '#f5f3ff', border: '1.5px solid #ddd6fe', borderRadius: 10, padding: '12px 16px', marginBottom: 22, display: 'flex', alignItems: 'center', gap: 12 }}>
            <span style={{ fontSize: 22 }}>🎯</span>
            <div>
              <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, fontSize: 14, color: '#3730a3' }}>
                You are creating a {examData.total_marks || '?'}-mark exam
              </div>
              <div style={{ fontSize: 12, color: '#4338ca' }}>
                In step 2 you must add questions that total exactly <strong>{examData.total_marks || '?'} marks</strong>. You can use AI generation or add manually.
              </div>
            </div>
          </div>

          <button className="btn btn-primary btn-lg" onClick={handleExamCreate} style={{ width: '100%' }}>
            Create Exam &amp; Add Questions →
          </button>
        </div>
      )}

      {/* ════════════════ STEP 2 ════════════════ */}
      {step === 2 && createdExam && (
        <div>
          {/* Abandon button */}
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 14 }}>
            <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, fontSize: 18, color: '#0f0f1a' }}>
              {createdExam.title}
            </div>
            <button onClick={() => setShowAbandonModal(true)}
              style={{ padding: '6px 14px', background: '#fff', border: '1px solid #fecaca', borderRadius: 8, fontSize: 12, fontWeight: 700, color: '#dc2626', cursor: 'pointer' }}>
              {questionCount === 0 ? '🗑 Cancel & Delete' : '← Save as Draft'}
            </button>
          </div>

          {/* Marks tracker */}
          <div style={{ background: bannerBg, border: `1.5px solid ${bannerBdr}`, borderRadius: 12, padding: '14px 18px', marginBottom: 8 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 10 }}>
              <div style={{ display: 'flex', gap: 20, alignItems: 'center', flexWrap: 'wrap' }}>
                {[
                  { label: 'QUESTIONS',   value: String(questionCount) },
                  { label: 'MARKS ADDED', value: `${currentMarks} / ${examTotal}`, color: marksColor },
                  { label: 'REMAINING',   value: marksOver ? `-${Math.abs(marksLeft)}` : `+${marksLeft}`, color: marksColor },
                ].map((s, i) => (
                  <div key={i} style={{ textAlign: 'center' }}>
                    <div style={{ fontSize: 9, color: '#9ca3af', fontFamily: 'JetBrains Mono,monospace', letterSpacing: 1, marginBottom: 2 }}>{s.label}</div>
                    <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 800, fontSize: 22, color: s.color || '#0f0f1a', lineHeight: 1 }}>{s.value}</div>
                  </div>
                ))}
                <div style={{ textAlign: 'center' }}>
                  <div style={{ fontSize: 9, color: '#9ca3af', fontFamily: 'JetBrains Mono,monospace', letterSpacing: 1, marginBottom: 2 }}>STATUS</div>
                  <div style={{ fontSize: 13, fontWeight: 700 }}>
                    {marksMatch ? '✅ Complete' : marksOver ? '⛔ Over limit' : `⚠ Need ${marksLeft} more`}
                  </div>
                </div>
              </div>
              <div style={{ display: 'flex', gap: 8 }}>
                {marksMatch && !isPublished && (
                  <button onClick={handlePublish}
                    style={{ padding: '9px 20px', background: 'linear-gradient(135deg,#16a34a,#15803d)', color: '#fff', border: 'none', borderRadius: 9, fontWeight: 800, fontSize: 13, cursor: 'pointer', boxShadow: '0 4px 14px rgba(22,163,74,.3)' }}>
                    🚀 Publish Exam
                  </button>
                )}
                {isPublished && (
                  <span style={{ padding: '9px 16px', background: '#dcfce7', color: '#16a34a', borderRadius: 9, fontWeight: 700, fontSize: 12 }}>
                    🟢 Published
                  </span>
                )}
                {!marksMatch && !marksOver && (
                  <div style={{ padding: '9px 16px', background: '#fef9c3', border: '1px solid #fde68a', borderRadius: 9, fontSize: 12, color: '#713f12', fontWeight: 600 }}>
                    Add {marksLeft} more mark{marksLeft !== 1 ? 's' : ''} to publish
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Progress bar */}
          <div style={{ height: 8, background: '#f3f4f6', borderRadius: 4, marginBottom: 18, overflow: 'hidden' }}>
            <div style={{ height: '100%', borderRadius: 4, transition: 'width .4s', width: `${pct}%`, background: `linear-gradient(90deg,${barColor}88,${barColor})` }}/>
          </div>

          {/* Tabs */}
          <div style={{ display: 'flex', gap: 2, background: '#f3f4f6', padding: 3, borderRadius: 10, marginBottom: 18, border: '1px solid #e5e7eb' }}>
            {[
              { k: 'ai',      l: '🤖 AI Generate' },
              { k: 'manual',  l: '✏️ Manual Add' },
              { k: 'preview', l: `👁 Saved (${questionCount})` },
            ].map(t => (
              <button key={t.k}
                onClick={async () => { if (t.k === 'preview') await store.loadExamQuestions(createdExam.exam_id); setAddTab(t.k); }}
                style={{ flex: 1, padding: '8px 12px', borderRadius: 8, border: 'none', cursor: 'pointer', fontSize: 13, fontWeight: 600, background: addTab === t.k ? '#fff' : 'transparent', color: addTab === t.k ? '#0f0f1a' : '#6b7280', boxShadow: addTab === t.k ? '0 1px 4px rgba(0,0,0,.08)' : '', transition: 'all .15s' }}>
                {t.l}
              </button>
            ))}
          </div>

          {/* ── AI TAB ── */}
          {addTab === 'ai' && (
            <div style={{ background: '#fff', border: '1px solid #e8e8f0', borderRadius: 14, padding: 22, boxShadow: '0 1px 3px rgba(0,0,0,.05)' }}>
              <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, fontSize: 15, color: '#0f0f1a', marginBottom: 16 }}>🤖 AI Question Generator</div>

              {marksLeft <= 0 && !marksMatch && (
                <div style={{ background: '#fef2f2', border: '1px solid #fecaca', borderRadius: 9, padding: '10px 14px', marginBottom: 14, fontSize: 13, color: '#dc2626', fontWeight: 600 }}>
                  ⛔ Marks are over the limit! Go to Saved tab and remove questions first.
                </div>
              )}
              {marksMatch && (
                <div style={{ background: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: 9, padding: '10px 14px', marginBottom: 14, fontSize: 13, color: '#16a34a', fontWeight: 600 }}>
                  ✅ Exam is complete ({examTotal} marks). Publish it above or remove questions to add different ones.
                </div>
              )}

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 14 }}>
                <div>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>TOPIC</label>
                  <input className="form-input" value={aiConfig.topic} onChange={e => setAiConfig(c => ({ ...c, topic: e.target.value }))} placeholder="e.g. Neural Networks, SQL Joins..."/>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>QUESTION TYPE</label>
                  <select className="form-select" value={aiConfig.type} onChange={e => setAiConfig(c => ({ ...c, type: e.target.value }))}>
                    <option value="MCQ">Multiple Choice</option>
                    <option value="TRUE_FALSE">True / False</option>
                    <option value="SHORT_ANSWER">Short Answer</option>
                    <option value="DESCRIPTIVE">Descriptive</option>
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>DIFFICULTY</label>
                  <select className="form-select" value={aiConfig.difficulty} onChange={e => setAiConfig(c => ({ ...c, difficulty: e.target.value }))}>
                    <option>Easy</option><option>Medium</option><option>Hard</option>
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>
                    COUNT &nbsp;<span style={{ color: '#9ca3af', fontWeight: 400 }}>({marksLeft} marks left)</span>
                  </label>
                  <select className="form-select" value={aiConfig.count} onChange={e => setAiConfig(c => ({ ...c, count: e.target.value }))}>
                    {[3, 5, 7, 10].map(n => <option key={n} value={n}>{n} questions</option>)}
                  </select>
                </div>
              </div>

              <div style={{ background: '#f5f3ff', border: '1px solid #ddd6fe', borderRadius: 8, padding: '9px 14px', marginBottom: 14, fontSize: 12, color: '#4338ca' }}>
                💡 Marks will be auto-distributed to fit exactly within your {marksLeft} remaining mark budget. You can adjust them before saving.
              </div>

              <button className="btn btn-primary" onClick={handleGenerate} disabled={generating || marksLeft <= 0}>
                {generating
                  ? <><div className="spinner" style={{ width: 13, height: 13 }}/>Generating...</>
                  : '⚡ Generate Questions'}
              </button>

              {aiError && <div style={{ background: '#fef2f2', border: '1px solid #fecaca', borderRadius: 8, padding: '9px 14px', marginTop: 12, fontSize: 13, color: '#dc2626' }}>{aiError}</div>}

              {generating && (
                <div style={{ background: '#f5f3ff', border: '1px solid #ddd6fe', borderRadius: 10, padding: 16, marginTop: 14 }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                      <div className="spinner"/>
                      <span style={{ fontSize: 13, color: '#4338ca' }}>Generating "{aiConfig.topic}" questions...</span>
                    </div>
                    <span style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 800, fontSize: 18, color: '#7c3aed' }}>{genProgress.current}/{genProgress.total}</span>
                  </div>
                  <div style={{ height: 6, background: '#ddd6fe', borderRadius: 3, overflow: 'hidden' }}>
                    <div style={{ height: '100%', borderRadius: 3, transition: 'width .4s', width: genProgress.total ? `${(genProgress.current / genProgress.total) * 100}%` : '5%', background: 'linear-gradient(90deg,#a78bfa,#7c3aed)' }}/>
                  </div>
                </div>
              )}

              {genQuestions.length > 0 && !generating && (
                <>
                  {/* Summary + actions */}
                  <div style={{ marginTop: 18, marginBottom: 12, padding: '10px 14px', background: '#f8f8fc', borderRadius: 9, border: '1px solid #e8e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 10 }}>
                    <div style={{ fontSize: 13 }}>
                      <span style={{ color: '#16a34a', fontWeight: 700 }}>✓ {genQuestions.filter(q => q._accepted).length} accepted</span>
                      <span style={{ margin: '0 8px', color: '#e5e7eb' }}>|</span>
                      <span style={{ color: '#dc2626' }}>✕ {genQuestions.filter(q => !q._accepted).length} rejected</span>
                      <span style={{ margin: '0 8px', color: '#e5e7eb' }}>|</span>
                      <span style={{ color: currentMarks + acceptedMarks > examTotal ? '#dc2626' : '#7c3aed', fontWeight: 700 }}>
                        {acceptedMarks} marks {currentMarks + acceptedMarks > examTotal ? `⛔ OVER by ${currentMarks + acceptedMarks - examTotal}` : `(${examTotal - currentMarks - acceptedMarks} still free)`}
                      </span>
                    </div>
                    <div style={{ display: 'flex', gap: 7 }}>
                      <button onClick={() => setGenQuestions(qs => qs.map(q => ({ ...q, _accepted: true })))}
                        style={{ padding: '5px 12px', background: '#fff', border: '1px solid #e5e7eb', borderRadius: 6, fontSize: 11, fontWeight: 600, color: '#374151', cursor: 'pointer' }}>All</button>
                      <button onClick={() => setGenQuestions(qs => qs.map(q => ({ ...q, _accepted: false })))}
                        style={{ padding: '5px 12px', background: '#fff', border: '1px solid #e5e7eb', borderRadius: 6, fontSize: 11, fontWeight: 600, color: '#374151', cursor: 'pointer' }}>None</button>
                      <button onClick={rebalanceMarks}
                        style={{ padding: '5px 12px', background: '#f5f3ff', border: '1px solid #ddd6fe', borderRadius: 6, fontSize: 11, fontWeight: 700, color: '#7c3aed', cursor: 'pointer' }}>
                        ⚖ Rebalance Marks
                      </button>
                      <button onClick={handleSaveAccepted} disabled={acceptedCount === 0 || allSaved}
                        style={{ padding: '5px 14px', background: acceptedCount > 0 && !allSaved ? 'linear-gradient(135deg,#16a34a,#15803d)' : '#d1d5db', color: '#fff', border: 'none', borderRadius: 6, fontSize: 12, fontWeight: 700, cursor: acceptedCount > 0 && !allSaved ? 'pointer' : 'not-allowed' }}>
                        💾 Save {acceptedCount} Questions
                      </button>
                    </div>
                  </div>

                  {genQuestions.map((q, i) => {
                    const isDupe = savedTexts.includes(q.question_text.trim().toLowerCase());
                    const accepted_total = genQuestions.filter((x,j)=>x._accepted&&!x._saved&&j!==i).reduce((s,x)=>s+Number(x.marks),0);
                    return (
                      <div key={q.question_id} style={{ background: q._saved ? '#f0fdf4' : isDupe ? '#fef2f2' : q._accepted ? '#fff' : '#fafafa', border: `1.5px solid ${q._saved ? '#bbf7d0' : isDupe ? '#fecaca' : q._accepted ? '#e8e8f0' : '#f3f4f6'}`, borderRadius: 11, padding: 16, marginBottom: 10, opacity: !q._accepted && !q._saved ? 0.55 : 1, transition: 'all .15s' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 12, marginBottom: 8 }}>
                          <div style={{ fontSize: 14, lineHeight: 1.55, color: '#0f0f1a', flex: 1 }}>
                            <span style={{ fontFamily: 'JetBrains Mono,monospace', fontSize: 10, color: '#9ca3af', marginRight: 8 }}>Q{i+1}</span>
                            {q.question_text}
                            {isDupe && <span style={{ marginLeft: 8, fontSize: 10, color: '#dc2626', background: '#fee2e2', padding: '2px 8px', borderRadius: 10 }}>DUPLICATE</span>}
                          </div>
                          <div style={{ display: 'flex', gap: 6, alignItems: 'center', flexShrink: 0 }}>
                            <span style={{ padding: '2px 8px', borderRadius: 20, background: q.difficulty === 'Easy' ? '#dcfce7' : q.difficulty === 'Hard' ? '#fee2e2' : '#fef3c7', color: q.difficulty === 'Easy' ? '#16a34a' : q.difficulty === 'Hard' ? '#dc2626' : '#d97706', fontSize: 10, fontWeight: 700 }}>{q.difficulty}</span>
                            {!q._saved && !isDupe && (
                              <div style={{ display: 'flex', alignItems: 'center', gap: 4, background: '#f5f3ff', border: '1px solid #ddd6fe', borderRadius: 7, padding: '4px 8px' }}>
                                <span style={{ fontSize: 10, color: '#7c3aed', fontFamily: 'JetBrains Mono,monospace' }}>pts</span>
                                <input type="number" min={1} max={examTotal} value={q.marks}
                                  onChange={e => editMarks(i, e.target.value)}
                                  style={{ width: 40, border: 'none', background: 'transparent', fontSize: 13, fontWeight: 800, color: '#6d28d9', textAlign: 'center', outline: 'none' }}/>
                              </div>
                            )}
                            {q._saved
                              ? <span style={{ padding: '4px 10px', background: '#dcfce7', color: '#16a34a', borderRadius: 7, fontSize: 11, fontWeight: 700 }}>✓ Saved</span>
                              : isDupe
                              ? <span style={{ padding: '4px 10px', background: '#fee2e2', color: '#dc2626', borderRadius: 7, fontSize: 11, fontWeight: 700 }}>Duplicate</span>
                              : (
                                <button onClick={() => toggleAccept(i)}
                                  style={{ padding: '5px 14px', borderRadius: 7, border: 'none', background: q._accepted ? '#fee2e2' : '#dcfce7', color: q._accepted ? '#dc2626' : '#16a34a', fontWeight: 700, fontSize: 12, cursor: 'pointer', minWidth: 78 }}>
                                  {q._accepted ? '✕ Reject' : '✓ Accept'}
                                </button>
                              )
                            }
                          </div>
                        </div>
                        {q.options && (
                          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 5, marginBottom: 6 }}>
                            {q.options.map((o, oi) => (
                              <div key={oi} style={{ fontSize: 12, padding: '5px 10px', borderRadius: 6, background: o.is_correct ? '#f0fdf4' : '#f8f8fc', color: o.is_correct ? '#16a34a' : '#6b7280', border: `1px solid ${o.is_correct ? '#bbf7d0' : 'transparent'}`, fontWeight: o.is_correct ? 700 : 400 }}>
                                {['A','B','C','D'][oi]}. {o.text} {o.is_correct && '✓'}
                              </div>
                            ))}
                          </div>
                        )}
                        {q.explanation && (
                          <div style={{ fontSize: 12, color: '#6b7280', padding: '6px 10px', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 6, marginTop: 4 }}>
                            💡 {q.explanation}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </>
              )}
            </div>
          )}

          {/* ── MANUAL TAB ── */}
          {addTab === 'manual' && (
            <div style={{ background: '#fff', border: '1px solid #e8e8f0', borderRadius: 14, padding: 22, boxShadow: '0 1px 3px rgba(0,0,0,.05)' }}>
              <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, fontSize: 15, color: '#0f0f1a', marginBottom: 16 }}>✏️ Add Question Manually</div>
              {marksLeft <= 0 ? (
                <div style={{ background: '#fef2f2', border: '1px solid #fecaca', borderRadius: 9, padding: '10px 14px', marginBottom: 14, fontSize: 13, color: '#dc2626', fontWeight: 600 }}>
                  ⛔ No marks remaining. Remove questions from Saved tab first.
                </div>
              ) : (
                <div style={{ background: '#f5f3ff', border: '1px solid #ddd6fe', borderRadius: 9, padding: '9px 14px', marginBottom: 14, fontSize: 12, color: '#4338ca' }}>
                  {marksLeft} marks remaining · This question's marks will be deducted from that budget
                </div>
              )}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 12, marginBottom: 12 }}>
                <div>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>TYPE</label>
                  <select className="form-select" value={manualQ.question_type} onChange={e => setManualQ(q => ({ ...q, question_type: e.target.value }))}>
                    <option value="MCQ">MCQ</option><option value="TRUE_FALSE">True/False</option>
                    <option value="SHORT_ANSWER">Short Answer</option><option value="DESCRIPTIVE">Descriptive</option>
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>DIFFICULTY</label>
                  <select className="form-select" value={manualQ.difficulty} onChange={e => setManualQ(q => ({ ...q, difficulty: e.target.value }))}>
                    <option>Easy</option><option>Medium</option><option>Hard</option>
                  </select>
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>MARKS (max {marksLeft})</label>
                  <input className="form-input" type="number" min={1} max={marksLeft} value={manualQ.marks}
                    onChange={e => setManualQ(q => ({ ...q, marks: Math.min(marksLeft, Math.max(1, Number(e.target.value))) }))}/>
                </div>
              </div>
              <div style={{ marginBottom: 12 }}>
                <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>QUESTION TEXT</label>
                <textarea className="form-textarea" value={manualQ.question_text} onChange={e => setManualQ(q => ({ ...q, question_text: e.target.value }))} placeholder="Enter the question..." style={{ minHeight: 80 }}/>
              </div>
              {manualQ.question_type === 'MCQ' && (
                <div style={{ marginBottom: 12 }}>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>OPTIONS</label>
                  {manualQ.options.map((o, i) => (
                    <input key={i} className="form-input" style={{ marginBottom: 7 }} value={o}
                      onChange={e => setManualQ(q => ({ ...q, options: q.options.map((x, xi) => xi === i ? e.target.value : x) }))}
                      placeholder={`Option ${['A','B','C','D'][i]}`}/>
                  ))}
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, marginTop: 8, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>CORRECT ANSWER</label>
                  <select className="form-select" value={manualQ.correct_answer} onChange={e => setManualQ(q => ({ ...q, correct_answer: e.target.value }))}>
                    <option value="">Select correct option...</option>
                    {['A','B','C','D'].map(l => <option key={l}>{l}</option>)}
                  </select>
                </div>
              )}
              {manualQ.question_type === 'TRUE_FALSE' && (
                <div style={{ marginBottom: 12 }}>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>CORRECT ANSWER</label>
                  <select className="form-select" value={manualQ.correct_answer} onChange={e => setManualQ(q => ({ ...q, correct_answer: e.target.value }))}>
                    <option value="">Select...</option><option>True</option><option>False</option>
                  </select>
                </div>
              )}
              {(manualQ.question_type === 'SHORT_ANSWER' || manualQ.question_type === 'DESCRIPTIVE') && (
                <div style={{ marginBottom: 12 }}>
                  <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>MODEL ANSWER</label>
                  <textarea className="form-textarea" style={{ minHeight: 90 }} value={manualQ.correct_answer}
                    onChange={e => setManualQ(q => ({ ...q, correct_answer: e.target.value }))} placeholder="Reference answer for AI grading..."/>
                </div>
              )}
              <div style={{ marginBottom: 16 }}>
                <label style={{ display: 'block', fontSize: 10, fontWeight: 700, color: '#7c3aed', marginBottom: 5, textTransform: 'uppercase', letterSpacing: 1.5, fontFamily: 'JetBrains Mono,monospace' }}>EXPLANATION (optional)</label>
                <input className="form-input" value={manualQ.explanation} onChange={e => setManualQ(q => ({ ...q, explanation: e.target.value }))} placeholder="Brief explanation..."/>
              </div>
              <button className="btn btn-primary" onClick={handleAddManual} disabled={marksLeft <= 0}>
                Add Question
              </button>
            </div>
          )}

          {/* ── SAVED TAB ── */}
          {addTab === 'preview' && (
            <div style={{ background: '#fff', border: '1px solid #e8e8f0', borderRadius: 14, padding: 22, boxShadow: '0 1px 3px rgba(0,0,0,.05)' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, fontSize: 15, color: '#0f0f1a' }}>
                  Saved Questions ({questionCount})
                </div>
                <div style={{ fontSize: 13, fontWeight: 700, color: marksColor }}>
                  {currentMarks} / {examTotal} marks {marksMatch ? '✓' : marksOver ? '⛔ OVER' : ''}
                </div>
              </div>
              {marksOver && (
                <div style={{ background: '#fef2f2', border: '1px solid #fecaca', borderRadius: 9, padding: '10px 14px', marginBottom: 14, fontSize: 13, color: '#dc2626', fontWeight: 600 }}>
                  ⛔ {Math.abs(marksLeft)} marks over the limit! Remove questions to fix this.
                </div>
              )}
              {questionCount === 0 ? (
                <div style={{ textAlign: 'center', padding: 48 }}>
                  <div style={{ fontSize: 36, marginBottom: 12, opacity: .2 }}>📭</div>
                  <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 700, fontSize: 15, color: '#374151', marginBottom: 6 }}>No questions yet</div>
                  <div style={{ fontSize: 13, color: '#9ca3af' }}>Use AI Generate or Manual Add tab to add questions</div>
                </div>
              ) : savedQuestions.map((q, i) => (
                <div key={q.question_id} style={{ border: '1px solid #e8e8f0', borderRadius: 10, padding: 14, marginBottom: 10, background: '#f8f8fc' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 10 }}>
                    <div style={{ fontSize: 14, color: '#0f0f1a', flex: 1, lineHeight: 1.55 }}>
                      <span style={{ fontFamily: 'JetBrains Mono,monospace', fontSize: 10, color: '#9ca3af', marginRight: 7 }}>Q{i+1}</span>
                      {q.question_text}
                    </div>
                    <div style={{ display: 'flex', gap: 6, flexShrink: 0, alignItems: 'center' }}>
                      <span style={{ padding: '2px 8px', borderRadius: 20, background: '#ede9fe', color: '#7c3aed', fontSize: 10, fontWeight: 700 }}>{q.marks} pts</span>
                      <span style={{ padding: '2px 8px', borderRadius: 20, background: '#f3f4f6', color: '#6b7280', fontSize: 10, fontWeight: 600 }}>{q.question_type}</span>
                      <button onClick={() => { store.removeQuestion(q.question_id); store.addToast('Question removed', 'info'); }}
                        style={{ padding: '4px 12px', background: '#fff', border: '1px solid #fecaca', borderRadius: 7, fontSize: 12, color: '#dc2626', fontWeight: 700, cursor: 'pointer' }}>
                        🗑
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ── Abandon modal ── */}
      {showAbandonModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.45)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20 }}>
          <div style={{ background: '#fff', borderRadius: 16, padding: 28, maxWidth: 440, width: '100%', boxShadow: '0 24px 60px rgba(0,0,0,.2)' }}>
            <div style={{ fontSize: 36, marginBottom: 14, textAlign: 'center' }}>
              {questionCount === 0 ? '🗑️' : '📋'}
            </div>
            <div style={{ fontFamily: 'Space Grotesk,sans-serif', fontWeight: 800, fontSize: 18, color: '#0f0f1a', marginBottom: 10, textAlign: 'center' }}>
              {questionCount === 0 ? 'Delete This Exam?' : 'Leave Exam Creation?'}
            </div>
            <div style={{ fontSize: 14, color: '#374151', lineHeight: 1.7, marginBottom: 20, textAlign: 'center' }}>
              {questionCount === 0
                ? 'This exam has no questions. It will be permanently deleted if you leave now.'
                : `This exam has ${questionCount} question(s) worth ${currentMarks}/${examTotal} marks. It will be saved as a draft — you can continue adding questions later from the Exams tab.`}
            </div>
            {!marksMatch && questionCount > 0 && (
              <div style={{ background: '#fef9c3', border: '1px solid #fde68a', borderRadius: 9, padding: '9px 14px', marginBottom: 16, fontSize: 12, color: '#713f12' }}>
                ⚠ Reminder: You still need {marksLeft} more mark{marksLeft !== 1 ? 's' : ''} to complete this exam ({currentMarks}/{examTotal} done).
              </div>
            )}
            <div style={{ display: 'flex', gap: 10 }}>
              <button onClick={() => setShowAbandonModal(false)}
                style={{ flex: 1, padding: '10px', background: '#fff', border: '1px solid #e5e7eb', borderRadius: 9, fontWeight: 700, fontSize: 13, color: '#374151', cursor: 'pointer' }}>
                Keep Editing
              </button>
              <button onClick={handleAbandon}
                style={{ flex: 1, padding: '10px', background: questionCount === 0 ? '#dc2626' : '#7c3aed', color: '#fff', border: 'none', borderRadius: 9, fontWeight: 700, fontSize: 13, cursor: 'pointer' }}>
                {questionCount === 0 ? 'Yes, Delete' : 'Save as Draft'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CreateExam;
